-- HQ full product signal coverage
-- Live migration 20260809212644. Expands the HQ nervous system from basic lifecycle
-- telemetry to learning, Twin, VibeLearn, VibeLab, billing and school operations.

create or replace function public.hq_capture_product_change()
returns trigger language plpgsql security definer set search_path=public as $$
declare
 n jsonb:=to_jsonb(new); o jsonb:=case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end;
 v_event_type text; v_actor_id uuid; v_actor_role text; v_school_id uuid; v_entity_id uuid;
 v_source_id text:=coalesce(n->>'id',n->>'attempt_id',n->>'session_id',n->>'submission_id',n->>'subscription_id');
 v_status text:=coalesce(n->>'status',n->>'state',''); v_old_status text:=coalesce(o->>'status',o->>'state','');
 v_actor_text text:=coalesce(n->>'student_id',n->>'teacher_id',n->>'user_id',n->>'created_by',n->>'parent_id',n->>'learner_id',n->>'viewer_id',n->>'profile_id',n->>'staff_id',n->>'recorded_by');
 v_school_text text:=n->>'school_id'; v_key text; v_metadata jsonb;
begin
 if tg_op='UPDATE' and n=o then return new; end if;
 v_event_type:=case tg_table_name
  when 'attendance' then case when tg_op='INSERT' then 'attendance.recorded' else 'attendance.updated' end
  when 'assessment_attempts' then case when tg_op='INSERT' then 'assessment.started' when n->>'status'='submitted' and o->>'status' is distinct from n->>'status' then 'assessment.submitted' else 'assessment.status_changed' end
  when 'assessment_gradebook_entries' then 'assessment.graded'
  when 'assessment_interventions' then case when tg_op='INSERT' then 'learning.intervention_created' when n->>'status'='completed' and o->>'status' is distinct from n->>'status' then 'learning.intervention_completed' else 'learning.intervention_updated' end
  when 'lesson_evidence' then 'lesson.evidence_added' when 'lesson_reflections' then 'lesson.reflected'
  when 'student_learning_events' then 'student.learning_event' when 'student_learning_transformation_events' then 'student.learning_transformation'
  when 'student_twin_adaptation_events' then 'twin.adapted' when 'student_twin_calibration_events' then 'twin.calibrated' when 'student_twin_intervention_effects' then 'twin.intervention_effect'
  when 'student_task_execution_receipts' then 'student.task_executed' when 'parent_messages' then 'communication.parent_message'
  when 'vibelab_sessions' then case when tg_op='INSERT' then 'vibelab.session_started' when n->>'status'='completed' and o->>'status' is distinct from n->>'status' then 'vibelab.session_completed' else 'vibelab.session_status_changed' end
  when 'vibelab_interactions' then 'vibelab.interaction'
  when 'vibe_reading_sessions' then case when tg_op='INSERT' then 'vibelearn.reading_started' when n->>'completed_at' is not null and o->>'completed_at' is null then 'vibelearn.reading_completed' when n->>'ended_at' is not null and o->>'ended_at' is null then 'vibelearn.reading_ended' else 'vibelearn.reading_progressed' end
  when 'vibe_reading_progress' then case when coalesce((n->>'progress_percent')::int,0)>=100 and coalesce((o->>'progress_percent')::int,0)<100 then 'vibelearn.content_completed' else 'vibelearn.progress_updated' end
  when 'exercise_submissions' then 'learning.exercise_submitted' when 'project_submissions' then 'learning.project_submitted'
  when 'billing_subscriptions' then case when tg_op='INSERT' then 'billing.subscription_started' when n->>'status' is distinct from o->>'status' then 'billing.subscription_status_changed' else 'billing.subscription_updated' end
  when 'billing_subscription_events' then case when lower(coalesce(n->>'event_type','')) ~ '(fail|past_due|declin|error)' then 'billing.failure' else 'billing.event' end
  when 'schools' then case when tg_op='INSERT' then 'school.created' when n->>'status' is distinct from o->>'status' then 'school.status_changed' else 'school.updated' end
  when 'school_members' then case when tg_op='INSERT' then 'school.member_added' else 'school.member_changed' end
  when 'staff_attendance' then 'school.staff_attendance_recorded' when 'admin_staff_attendance' then 'school.staff_attendance_recorded'
  else 'product.data_changed' end;
 begin if v_actor_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then v_actor_id:=v_actor_text::uuid; end if; exception when others then v_actor_id:=null; end;
 begin if v_school_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then v_school_id:=v_school_text::uuid; end if; exception when others then v_school_id:=null; end;
 begin if v_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then v_entity_id:=v_source_id::uuid; end if; exception when others then v_entity_id:=null; end;
 v_actor_role:=case when tg_table_name in ('schools','school_members','staff_attendance','admin_staff_attendance') then 'school_admin' when tg_table_name like 'billing_%' then 'billing' when n ? 'teacher_id' then 'teacher' when n ? 'parent_id' then 'parent' when n ? 'student_id' or n ? 'learner_id' or n ? 'viewer_id' then 'student' else null end;
 v_metadata:=jsonb_strip_nulls(jsonb_build_object('source_id',v_source_id,'status',nullif(v_status,''),'old_status',nullif(v_old_status,''),'operation',tg_op,'table',tg_table_name,'event_type_source',n->>'event_type','percentage',n->>'percentage','score',n->>'score','max_score',n->>'max_score','progress_percent',n->>'progress_percent','duration_seconds',n->>'duration_seconds','effectiveness_score',n->>'effectiveness_score','confidence',coalesce(n->>'confidence',n->>'confidence_score'),'mastery_change',n->>'mastery_change','end_reason',n->>'end_reason','interaction_type',n->>'interaction_type','plan_key',n->>'plan_key','amount',n->>'amount','product_key',case when tg_table_name like 'billing_%' then 'billing' when tg_table_name like 'vibelab_%' then 'vibelabs' when tg_table_name like 'vibe_reading_%' then 'vibelearn' when tg_table_name like 'student_twin_%' then 'twin' when tg_table_name in ('schools','school_members','staff_attendance','admin_staff_attendance') then 'school_admin' else null end));
 v_key:=format('capture:%s:%s:%s:%s:%s',tg_table_name,tg_op,coalesce(v_source_id,md5(n::text)),coalesce(v_status,''),coalesce(n->>'updated_at',n->>'occurred_at',n->>'created_at',''));
 insert into public.platform_events(event_type,actor_id,actor_role,school_id,entity_type,entity_id,metadata,idempotency_key) values(v_event_type,v_actor_id,v_actor_role,v_school_id,tg_table_name,v_entity_id,v_metadata,v_key) on conflict (idempotency_key) where idempotency_key is not null do nothing;
 return new;
end $$;

insert into public.hq_product_event_contract(event_type,product_key,category,department_key,severity,creates_work,creates_incident,decision_required,verification_event_type,max_unverified_minutes,active) values
('attendance.updated','teacher','teaching','learning','info',false,false,false,null,120,true),('assessment.submitted','student','learning','learning','info',false,false,false,'assessment.graded',1440,true),('assessment.status_changed','student','learning','learning','info',false,false,false,null,240,true),('learning.intervention_created','teacher','learning','learning','medium',true,false,false,'learning.intervention_completed',10080,true),('learning.intervention_updated','teacher','learning','learning','info',false,false,false,null,1440,true),('learning.intervention_completed','teacher','learning','learning','info',false,false,false,null,1440,true),('student.learning_event','student','learning','learning','info',false,false,false,null,240,true),('student.learning_transformation','student','learning','learning','info',false,false,false,null,1440,true),('twin.calibrated','twin','learning','learning','info',false,false,false,null,1440,true),('twin.intervention_effect','twin','learning','learning','info',false,false,false,null,1440,true),('vibelearn.reading_progressed','vibelearn','learning','learning','info',false,false,false,null,240,true),('vibelearn.reading_ended','vibelearn','learning','learning','info',false,false,false,null,240,true),('vibelearn.reading_completed','vibelearn','learning','learning','info',false,false,false,null,1440,true),('vibelearn.progress_updated','vibelearn','learning','learning','info',false,false,false,null,240,true),('vibelearn.content_completed','vibelearn','learning','learning','info',false,false,false,null,1440,true),('vibelab.interaction','vibelabs','learning','learning','info',false,false,false,null,240,true),('vibelab.session_completed','vibelabs','learning','learning','info',false,false,false,null,1440,true),('billing.subscription_started','billing','billing','finance','info',false,false,false,null,1440,true),('billing.subscription_status_changed','billing','billing','finance','medium',true,false,false,null,240,true),('billing.subscription_updated','billing','billing','finance','info',false,false,false,null,1440,true),('billing.event','billing','billing','finance','info',false,false,false,null,1440,true),('school.created','school_admin','operations','operations','info',false,false,false,null,1440,true),('school.updated','school_admin','operations','operations','info',false,false,false,null,1440,true),('school.status_changed','school_admin','operations','operations','medium',true,false,false,null,240,true),('school.member_added','school_admin','operations','operations','info',false,false,false,null,1440,true),('school.member_changed','school_admin','operations','operations','medium',true,false,false,null,240,true),('school.staff_attendance_recorded','school_admin','operations','operations','info',false,false,false,null,1440,true),('learning.low_score','student','learning','learning','medium',true,false,false,'learning.intervention_completed',10080,true),('twin.low_effectiveness','twin','learning','learning','medium',true,false,false,'twin.intervention_effect',10080,true),('vibelearn.abandoned','vibelearn','learning','learning','medium',true,false,false,null,1440,true),('vibelab.failed','vibelabs','quality','quality','high',true,true,false,'vibelab.session_completed',240,true)
on conflict(event_type) do update set product_key=excluded.product_key,category=excluded.category,department_key=excluded.department_key,severity=excluded.severity,creates_work=excluded.creates_work,creates_incident=excluded.creates_incident,decision_required=excluded.decision_required,verification_event_type=excluded.verification_event_type,max_unverified_minutes=excluded.max_unverified_minutes,active=true,updated_at=now();

create or replace function public.hq_derive_product_signal() returns trigger language plpgsql security definer set search_path=public as $$
declare v_type text; v_key text; v_pct numeric; v_eff numeric; v_status text;
begin
 if new.event_type='assessment.graded' then begin v_pct:=(new.metadata->>'percentage')::numeric; exception when others then v_pct:=null; end; if v_pct is not null and v_pct<40 then v_type:='learning.low_score'; end if;
 elsif new.event_type='twin.intervention_effect' then begin v_eff:=(new.metadata->>'effectiveness_score')::numeric; exception when others then v_eff:=null; end; if v_eff is not null and v_eff<0.35 then v_type:='twin.low_effectiveness'; end if;
 elsif new.event_type='vibelearn.reading_ended' then begin v_pct:=coalesce((new.metadata->>'progress_percent')::numeric,0); exception when others then v_pct:=0; end; if v_pct<20 and coalesce(new.metadata->>'end_reason','') not in ('completed','complete') then v_type:='vibelearn.abandoned'; end if;
 elsif new.event_type in ('vibelab.session_status_changed','vibelab.session_completed') then v_status:=lower(coalesce(new.metadata->>'status','')); if v_status in ('failed','error','broken') then v_type:='vibelab.failed'; end if; end if;
 if v_type is not null then v_key:='derived:'||new.id::text||':'||v_type; insert into public.platform_events(event_type,actor_id,actor_role,school_id,entity_type,entity_id,metadata,idempotency_key) values(v_type,new.actor_id,new.actor_role,new.school_id,new.entity_type,new.entity_id,new.metadata||jsonb_build_object('source_event_id',new.id),v_key) on conflict(idempotency_key) where idempotency_key is not null do nothing; end if;
 return new;
end $$;
drop trigger if exists trg_hq_derive_product_signal on public.platform_events; create trigger trg_hq_derive_product_signal after insert on public.platform_events for each row execute function public.hq_derive_product_signal();

do $$ declare t text; begin foreach t in array array['assessment_interventions','student_learning_events','student_learning_transformation_events','student_twin_calibration_events','student_twin_intervention_effects','vibelab_interactions','vibe_reading_progress','billing_subscriptions','billing_subscription_events','school_members','staff_attendance','admin_staff_attendance'] loop if to_regclass('public.'||t) is not null then execute format('drop trigger if exists trg_hq_product_capture on public.%I',t); execute format('create trigger trg_hq_product_capture after insert or update on public.%I for each row execute function public.hq_capture_product_change()',t); end if; end loop; end $$;
drop trigger if exists trg_hq_product_capture on public.schools; create trigger trg_hq_product_capture after insert or update on public.schools for each row execute function public.hq_capture_product_change();